1	/****************************************************************************
2	 * apps/examples/uvc_test/uvc_test.c
3	 *
4	 * USB Camera (UVC) live preview on framebuffer/LCD
5	 * Captures YUYV frames and displays them on /dev/lcd0 in real time.
6	 ****************************************************************************/
7	
8	#include <nuttx/config.h>
9	#include <stdio.h>
10	#include <stdlib.h>
11	#include <string.h>
12	#include <errno.h>
13	#include <fcntl.h>
14	#include <unistd.h>
15	#include <syslog.h>
16	#include <sys/ioctl.h>
17	#include <sys/time.h>
18	
19	#include <nuttx/video/video.h>
20	#include <nuttx/video/v4l2_cap.h>
21	#include <nuttx/video/fb.h>
22	#include <nuttx/lcd/lcd_dev.h>
23	
24	/****************************************************************************
25	 * Pre-processor Definitions
26	 ****************************************************************************/
27	
28	#define VIDEO_DEV_PATH    "/dev/video"
29	#define FB_DEV_PATH       "/dev/lcd0"
30	#define TEST_WIDTH        320
31	#define TEST_HEIGHT       240
32	#define TEST_BUF_COUNT    6   /* Deeper queue: more vacant buffers for the UVC
33	                               * stream thread to rotate through, so it never
34	                               * wraps onto the buffer the app is copying out.
35	                               */
36	#define PREVIEW_FRAMES    300   /* ~10s at 30fps; 0 = run forever */
37	#define SAVE_FRAMES       10    /* Save first N frames as .yuv files to /data/ */
38	
39	/****************************************************************************
40	 * Private Types
41	 ****************************************************************************/
42	
43	struct v_buffer
44	{
45	  uint8_t *start;
46	  uint32_t length;
47	};
48	
49	/****************************************************************************
50	 * Private Data
51	 ****************************************************************************/
52	
53	static struct fb_videoinfo_s g_vinfo;
54	static int                   g_fbfd = -1;
55	static int                   g_recfd = -1;  /* /data/capture.yuv */
56	static uint16_t              g_rgbbuf[TEST_WIDTH * TEST_HEIGHT];
57	
58	/* Private snapshot of one captured frame (YUYV), so the shared V4L2 capture
59	 * buffer can be requeued immediately and not be overwritten mid-processing.
60	 */
61	
62	static uint8_t               g_framecopy[TEST_WIDTH * TEST_HEIGHT * 2];
63	
64	/****************************************************************************
65	 * Private Functions
66	 ****************************************************************************/
67	
68	/* Clamp an int to [0,255] */
69	
70	static inline uint8_t clamp8(int v)
71	{
72	  if (v < 0)
73	    {
74	      return 0;
75	    }
76	
77	  if (v > 255)
78	    {
79	      return 255;
80	    }
81	
82	  return (uint8_t)v;
83	}
