85	/****************************************************************************
86	 * Name: fb_open
87	 *
88	 * Description:
89	 *   Open the framebuffer device and query its geometry.
90	 *
91	 ****************************************************************************/
92	
93	static int fb_open(void)
94	{
95	  int ret;
96	
97	  g_fbfd = open(FB_DEV_PATH, O_RDWR);
98	  if (g_fbfd < 0)
99	    {
100	      printf("ERROR: open %s failed: %d\n", FB_DEV_PATH, errno);
101	      return -errno;
102	    }
103	
104	  /* /dev/lcd0 is an lcddev character device, use LCDDEVIO_GETVIDEOINFO */
105	
106	  ret = ioctl(g_fbfd, LCDDEVIO_GETVIDEOINFO, (uintptr_t)&g_vinfo);
107	  if (ret < 0)
108	    {
109	      printf("ERROR: LCDDEVIO_GETVIDEOINFO failed: %d\n", errno);
110	      close(g_fbfd);
111	      g_fbfd = -1;
112	      return -errno;
113	    }
114	
115	  printf("LCD: %ux%u fmt=%u\n", g_vinfo.xres, g_vinfo.yres, g_vinfo.fmt);
116	
117	  /* Also emit to syslog so it lands in the serial log for diagnosis. */
118	
119	  syslog(LOG_ERR, "UVCTEST LCD: xres=%u yres=%u fmt=%u\n",
120	         g_vinfo.xres, g_vinfo.yres, g_vinfo.fmt);
121	
122	  return OK;
123	}
