125	/****************************************************************************
126	 * Name: fb_update
127	 *
128	 * Description:
129	 *   Notify the framebuffer driver that the content changed (for LCD
130	 *   drivers that need an explicit flush).
131	 *
132	 ****************************************************************************/
133	
134	static void fb_blit(uint32_t w, uint32_t h)
135	{
136	  struct lcddev_area_s area;
137	
138	  memset(&area, 0, sizeof(area));
139	  area.row_start = 0;
140	  area.row_end   = h - 1;
141	  area.col_start = 0;
142	  area.col_end   = w - 1;
143	  area.stride    = w * 2;          /* RGB565: 2 bytes/pixel */
144	  area.data      = (FAR uint8_t *)g_rgbbuf;
145	
146	  ioctl(g_fbfd, LCDDEVIO_PUTAREA, (uintptr_t)&area);
147	}
