149	/****************************************************************************
150	 * Name: yuyv_to_fb
151	 *
152	 * Description:
153	 *   Convert a YUYV 4:2:2 frame to the framebuffer's RGB565 format and
154	 *   blit it centered on the screen.
155	 *
156	 ****************************************************************************/
157	
158	static void yuyv_to_fb(FAR const uint8_t *yuyv, uint32_t len)
159	{
160	  /* The camera frame is TEST_WIDTH x TEST_HEIGHT (320x240).  The panel may be
161	   * narrower/taller (e.g. ILI9341 is 240x320 portrait).  Blit only the region
162	   * that fits BOTH the camera frame and the panel, and use the panel width as
163	   * the row stride so each source row lands at the correct column on screen.
164	   * Writing 320-wide rows to a 240-wide panel is exactly what produced the
165	   * diagonal "stripe/tear" artifact.
166	   */
167	
168	  uint32_t panel_w = (g_vinfo.xres > 0) ? g_vinfo.xres : TEST_WIDTH;
169	  uint32_t panel_h = (g_vinfo.yres > 0) ? g_vinfo.yres : TEST_HEIGHT;
170	  uint32_t cpw = (panel_w < TEST_WIDTH)  ? panel_w : TEST_WIDTH;
171	  uint32_t cph = (panel_h < TEST_HEIGHT) ? panel_h : TEST_HEIGHT;
172	  uint32_t x;
173	  uint32_t y;
174	
175	  /* Each YUYV macro-pixel (4 bytes) encodes two pixels: Y0 U Y1 V.
176	   * The RGB565 destination is packed at the panel width (cpw) so the blit
177	   * stride matches the panel exactly.
178	   */
179	
180	  for (y = 0; y < cph; y++)
181	    {
182	      FAR const uint8_t *src = yuyv + y * TEST_WIDTH * 2;
183	      FAR uint16_t *dst = &g_rgbbuf[y * cpw];
184	
185	      if ((size_t)(y * TEST_WIDTH * 2) + cpw * 2 > len)
186	        {
187	          break;  /* Frame shorter than expected; stop early */
188	        }
189	
190	      for (x = 0; x + 1 < cpw; x += 2)
191	        {
192	          int y0 = src[0];
193	          int u  = src[1] - 128;
194	          int y1 = src[2];
195	          int v  = src[3] - 128;
196	          int r;
197	          int g;
198	          int b;
199	
200	          /* YUV -> RGB (BT.601) */
201	
202	          r = y0 + ((179 * v) >> 7);
203	          g = y0 - ((44 * u) >> 7) - ((91 * v) >> 7);
204	          b = y0 + ((227 * u) >> 7);
205	          dst[x] = ((clamp8(r) & 0xf8) << 8) |
206	                   ((clamp8(g) & 0xfc) << 3) |
207	                   (clamp8(b) >> 3);
208	
209	          r = y1 + ((179 * v) >> 7);
210	          g = y1 - ((44 * u) >> 7) - ((91 * v) >> 7);
211	          b = y1 + ((227 * u) >> 7);
212	          dst[x + 1] = ((clamp8(r) & 0xf8) << 8) |
213	                       ((clamp8(g) & 0xfc) << 3) |
214	                       (clamp8(b) >> 3);
215	
216	          src += 4;
217	        }
218	    }
219	
220	  fb_blit(cpw, cph);
221	}
