223	/****************************************************************************
224	 * Public Functions
225	 ****************************************************************************/
226	
227	int uvc_test_main(int argc, char *argv[])
228	{
229	  struct v4l2_format fmt;
230	  struct v4l2_requestbuffers req;
231	  struct v4l2_buffer buf;
232	  struct v_buffer *buffers;
233	  enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
234	  int fd;
235	  int ret;
236	  int i;
237	  int frames = 0;
238	
239	  printf("=== USB Camera (UVC) Live Preview ===\n");
240	
241	  /* Open the framebuffer for display */
242	
243	  ret = fb_open();
244	  if (ret < 0)
245	    {
246	      printf("ERROR: framebuffer init failed\n");
247	      return ERROR;
248	    }
249	
250	  /* DIAG: draw a static test pattern (colored horizontal bars) once, before
251	   * any camera data, to isolate the blit/LCD path from the camera data.  If
252	   * these bars appear clean and aligned, the LCD geometry+blit is correct and
253	   * any stripes are in the camera-frame layout; if the bars themselves are
254	   * striped/torn, the problem is in the blit or LCD driver path.
255	   */
256	
257	  {
258	    uint32_t pw = (g_vinfo.xres > 0) ? g_vinfo.xres : TEST_WIDTH;
259	    uint32_t ph = (g_vinfo.yres > 0) ? g_vinfo.yres : TEST_HEIGHT;
260	    uint32_t xx;
261	    uint32_t yy;
262	
263	    if (pw > TEST_WIDTH)  pw = TEST_WIDTH;
264	    if (ph > TEST_HEIGHT) ph = TEST_HEIGHT;
265	
266	    for (yy = 0; yy < ph; yy++)
267	      {
268	        uint16_t color;
269	        if      (yy < ph / 4)     color = 0xf800;  /* red    */
270	        else if (yy < ph / 2)     color = 0x07e0;  /* green  */
271	        else if (yy < ph * 3 / 4) color = 0x001f;  /* blue   */
272	        else                      color = 0xffff;  /* white  */
273	
274	        for (xx = 0; xx < pw; xx++)
275	          {
276	            g_rgbbuf[yy * pw + xx] = color;
277	          }
278	      }
279	
280	    fb_blit(pw, ph);
281	    syslog(LOG_ERR, "UVCTEST testpattern blitted %ux%u\n", pw, ph);
282	    sleep(2);
283	  }
284	
285	  /* Initialize video driver (creates /dev/video device) */
286	
287	  ret = capture_initialize(VIDEO_DEV_PATH);
288	  if (ret != 0)
289	    {
290	      printf("ERROR: Failed to initialize video: %d (errno=%d)\n", ret, errno);
291	      return ERROR;
292	    }
293	
294	  fd = open(VIDEO_DEV_PATH, O_RDWR);
295	  if (fd < 0)
296	    {
297	      printf("ERROR: Failed to open %s: %d\n", VIDEO_DEV_PATH, errno);
298	      return ERROR;
299	    }
300	
301	  /* Set YUYV format */
302	
303	  memset(&fmt, 0, sizeof(fmt));
304	  fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
305	  fmt.fmt.pix.width = TEST_WIDTH;
306	  fmt.fmt.pix.height = TEST_HEIGHT;
307	  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
308	  fmt.fmt.pix.field = V4L2_FIELD_NONE;
309	
310	  ret = ioctl(fd, VIDIOC_S_FMT, (uintptr_t)&fmt);
311	  if (ret < 0)
312	    {
313	      printf("ERROR: VIDIOC_S_FMT failed: %d\n", errno);
314	      goto err_close;
315	    }
316	
317	  if (fmt.fmt.pix.sizeimage == 0)
318	    {
319	      fmt.fmt.pix.sizeimage = TEST_WIDTH * TEST_HEIGHT * 2;
320	    }
321	
322	  /* Request buffers */
323	
324	  memset(&req, 0, sizeof(req));
325	  req.count = TEST_BUF_COUNT;
326	  req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
327	  req.memory = V4L2_MEMORY_USERPTR;
328	
329	  ret = ioctl(fd, VIDIOC_REQBUFS, (uintptr_t)&req);
330	  if (ret < 0)
331	    {
332	      printf("ERROR: VIDIOC_REQBUFS failed: %d\n", errno);
333	      goto err_close;
334	    }
335	
336	  buffers = (struct v_buffer *)malloc(req.count * sizeof(struct v_buffer));
337	  if (buffers == NULL)
338	    {
339	      printf("ERROR: Failed to allocate buffer array\n");
340	      goto err_close;
341	    }
342	
343	  for (i = 0; i < req.count; i++)
344	    {
345	      buffers[i].length = fmt.fmt.pix.sizeimage;
346	      buffers[i].start = (uint8_t *)memalign(64, buffers[i].length);
347	      if (buffers[i].start == NULL)
348	        {
349	          printf("ERROR: Failed to allocate buffer %d\n", i);
350	          goto err_free_buffers;
351	        }
352	
353	      memset(&buf, 0, sizeof(buf));
354	      buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
355	      buf.memory = V4L2_MEMORY_USERPTR;
356	      buf.index = i;
357	      buf.m.userptr = (uintptr_t)buffers[i].start;
358	      buf.length = buffers[i].length;
359	
360	      ret = ioctl(fd, VIDIOC_QBUF, (uintptr_t)&buf);
361	      if (ret < 0)
362	        {
363	          printf("ERROR: VIDIOC_QBUF failed for buffer %d: %d\n", i, errno);
364	          goto err_free_buffers;
365	        }
366	    }
367	
368	  /* Start streaming */
369	
370	  ret = ioctl(fd, VIDIOC_STREAMON, (uintptr_t)&type);
371	  if (ret < 0)
372	    {
373	      printf("ERROR: VIDIOC_STREAMON failed: %d\n", errno);
374	      goto err_free_buffers;
375	    }
376	
377	  printf("Live preview started (press Ctrl-C to stop)\n");
378	
379	  /* Preview loop */
380	
381	  while (PREVIEW_FRAMES == 0 || frames < PREVIEW_FRAMES)
382	    {
383	      memset(&buf, 0, sizeof(buf));
384	      buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
385	      buf.memory = V4L2_MEMORY_USERPTR;
386	
387	      ret = ioctl(fd, VIDIOC_DQBUF, (uintptr_t)&buf);
388	      if (ret < 0)
389	        {
390	          printf("ERROR: VIDIOC_DQBUF failed: %d\n", errno);
391	          break;
392	        }
393	
394	      /* Snapshot the frame into a private buffer, then IMMEDIATELY requeue
395	       * the V4L2 buffer.  The UVC stream thread writes the next frame into
396	       * one of the shared capture buffers concurrently; if the app kept a
397	       * buffer for the whole convert+SPI-blit time (slow, per-row SPI), the
398	       * driver could wrap around and overwrite the buffer mid-read, showing
399	       * up as a moving horizontal "tear" band.  Copying out fast (one memcpy)
400	       * and requeuing at once shrinks that window to almost nothing.
401	       */
402	
403	      {
404	        uint32_t n = buf.bytesused;
405	        if (n > sizeof(g_framecopy))
406	          {
407	            n = sizeof(g_framecopy);
408	          }
409	
410	        memcpy(g_framecopy, (const void *)buf.m.userptr, n);
411	
412	        /* Requeue immediately, before the slow convert + blit. */
413	
414	        ret = ioctl(fd, VIDIOC_QBUF, (uintptr_t)&buf);
415	        if (ret < 0)
416	          {
417	            printf("ERROR: VIDIOC_QBUF failed: %d\n", errno);
418	            break;
419	          }
420	
421	      /* Capture exactly ONE exact-size frame and display it.
422	       * This confirms whether a single 153600-byte frame renders
423	       * cleanly on the LCD (no stripes from SPI tearing).
424	       */
425	
426	      if (n >= (uint32_t)(TEST_WIDTH * TEST_HEIGHT * 2 * 95 / 100) &&
427	          n <= (uint32_t)(TEST_WIDTH * TEST_HEIGHT * 2 + 4096))
428	        {
429	          /* DIAG: check if row stride really is 640 bytes.
430	           * Dump first 8 bytes of row 0, row 1, row 2 at their
431	           * expected positions (640 bytes apart).  If row 1 starts
432	           * with non-YUYV values, the stride is wrong.
433	           */
434	
435	          /* DIAG: scan rows for YUYV continuity.  In a valid YUYV frame,
436	           * the Y value of pixel 0 in adjacent rows should be similar.
437	           * A sudden jump in Y0 indicates a row-boundary misalignment
438	           * in the assembled data.
439	           */
440	
441	          FAR const uint8_t *p = g_framecopy;
442	          uint32_t y;
443	          int prev_y0 = -1;
444	          int breaks = 0;
445	
446	          for (y = 0; y < TEST_HEIGHT; y++)
447	            {
448	              int y0 = p[y * TEST_WIDTH * 2];  /* Y of first pixel */
449	              if (prev_y0 >= 0 && abs(y0 - prev_y0) > 40)
450	                {
451	                  breaks++;
452	                  if (breaks <= 5)
453	                    {
454	                      syslog(LOG_ERR,
455	                        "ROW BREAK at y=%d: prev_Y=%d cur_Y=%d\n",
456	                        y, prev_y0, y0);
457	                    }
458	                }
459	              prev_y0 = y0;
460	            }
461	
462	          syslog(LOG_ERR, "ROW SCAN: %u rows, %d breaks\n",
463	                 TEST_HEIGHT, breaks);
464	
465	          /* Save this exact frame to file so we can compare PC vs LCD */
466	
467	          {
468	            int fd2 = open("/data/thisframe.yuv",
469	                           O_WRONLY | O_CREAT | O_TRUNC, 0666);
470	            if (fd2 >= 0)
471	              {
472	                write(fd2, g_framecopy, n);
473	                close(fd2);
474	                syslog(LOG_ERR, "Saved /data/thisframe.yuv (%u bytes)\n", n);
475	              }
476	          }
477	
478	          yuyv_to_fb(g_framecopy, n);
479	          syslog(LOG_ERR, "UVCTEST: single frame displayed (%u bytes)\n", n);
480	          break;  /* Display the frame and exit */
481	        }
482	
483	      }
484	    }
485	
486	  /* Stop streaming */
487	
488	  ioctl(fd, VIDIOC_STREAMOFF, (uintptr_t)&type);
489	  printf("Preview stopped after %d frames\n", frames);
490	
491	  ret = OK;
492	
493	err_free_buffers:
494	  for (i = 0; i < req.count; i++)
495	    {
496	      if (buffers[i].start != NULL)
497	        {
498	          free(buffers[i].start);
499	        }
500	    }
501	
502	  free(buffers);
503	
504	err_close:
505	  close(fd);
506	  if (g_fbfd >= 0)
507	    {
508	      close(g_fbfd);
509	    }
510	
511	  return ret;
512	}
