1051	static void usbhost_uvc_process_payload(FAR struct usbhost_uvc_s *priv,
1052	                                        FAR const uint8_t *payload,
1053	                                        size_t len)
1054	{
1055	  FAR const struct uvc_payload_header_s *header;
1056	  uint8_t header_len;
1057	  size_t data_len;
1058	  uint8_t fid;
1059	
1060	  if (len < 2)
1061	    {
1062	      return;
1063	    }
1064	
1065	  header = (FAR const struct uvc_payload_header_s *)payload;
1066	  header_len = header->bHeaderLength;
1067	  fid = header->bmHeaderInfo & UVC_HEADER_FID;
1068	
1069	  if (header_len > len)
1070	    {
1071	      return;
1072	    }
1073	
1074	  data_len = len - header_len;
1075	
1076	  /* DIAG: track payload data sizes within the frame being assembled.
1077	   * If any payload has data_len != 788 (full payload = 800-12), the
1078	   * cumulative offset shifts and produces the row-misalignment stripes.
1079	   */
1080	
1081	  {
1082	    static uint32_t non788;
1083	    static uint32_t total;
1084	    static bool     once;
1085	
1086	    total++;
1087	    if (data_len > 0 && data_len != 788)
1088	      {
1089	        non788++;
1090	        if (!once && priv->frame_offset > 100000)
1091	          {
1092	            once = true;
1093	            syslog(LOG_ERR, "NON788: data_len=%zu at frame_offset=%zu "
1094	                   "(total=%u non788=%u)\n",
1095	                   data_len, priv->frame_offset, total, non788);
1096	          }
1097	      }
1098	
1099	    if ((total % 2000) == 0)
1100	      {
1101	        syslog(LOG_ERR, "PLDIST: total=%u non788=%u (%.1f%%)\n",
1102	               total, non788, non788 * 100.0f / total);
1103	      }
1104	  }
1105	
1106	  /* DIAG: per-second throughput counter and EOF-to-EOF span measurement.
1107	   * Prints once per second: payloads/sec, data bytes/sec, total assembled
1108	   * bytes since last print, and how many EOFs were seen.
1109	   */
1110	
1111	  {
1112	    static uint32_t span_bytes;
1113	    static uint32_t span_fidflips;
1114	    static uint8_t  span_fid = 0xff;
1115	    static uint32_t sec_pls;      /* payloads this second */
1116	    static uint32_t sec_bytes;    /* data bytes this second */
1117	    static uint32_t sec_eofs;     /* EOFs this second */
1118	    static int      scnt;
1119	
1120	    bool eof = (header->bmHeaderInfo & UVC_HEADER_EOF) != 0;
1121	
1122	    sec_pls++;
1123	    sec_bytes += data_len;
1124	    if (eof) sec_eofs++;
1125	
1126	    /* Every 2000 payloads (~1/3 sec at 6000/s), log cumulative throughput. */
1127	
1128	    if ((sec_pls % 2000) == 0)
1129	      {
1130	        syslog(LOG_ERR,
1131	          "TP: pls=%u bytes=%u eofs=%u\n",
1132	          sec_pls, sec_bytes, sec_eofs);
1133	      }
1134	
1135	    if (span_fid != 0xff && fid != span_fid)
1136	      {
1137	        span_fidflips++;
1138	      }
1139	
1140	    span_fid = fid;
1141	    span_bytes += data_len;
1142	
1143	    if (eof)
1144	      {
1145	        if ((scnt++ % 30) == 0)
1146	          {
1147	            syslog(LOG_ERR, "SPAN(eof2eof): bytes=%u fidflips=%u\n",
1148	                   span_bytes, span_fidflips);
1149	          }
1150	
1151	        span_bytes = 0;
1152	        span_fidflips = 0;
1153	      }
1154	  }
1155	
1156	  /* Frame delimiting — dual EOF + FID with size gate (Linux UVC style).
1157	   *
1158	   * This camera toggles FID 11-35 times per frame and fires EOF at
1159	   * unpredictable byte positions.  The strategy:
1160	   *
1161	   *  1. FID toggle → deliver current frame (if ≥95% of expected size),
1162	   *     then reset.  This is the primary delimiter: each FID value
1163	   *     represents a distinct time window of camera data.
1164	   *
1165	   *  2. EOF → also deliver (if ≥95%), then reset.  This catches frames
1166	   *     where FID didn't toggle at the boundary.
1167	   *
1168	   *  3. Size gate: ≥95% of max_frame_size (Linux reference threshold).
1169	   *     Frames below this are dropped (partial/too short).
1170	   *
1171	   *  4. Max-size safety: if frame_offset reaches max_frame_size, deliver
1172	   *     immediately to prevent merging two frames.
1173	   */
1174	
1175	  /* Append data to frame buffer.  FID is tracked for DIAG only; it does NOT
1176	   * trigger delivery — this camera toggles FID ~20 times per frame, so
1177	   * FID-based delimiting would fragment each frame into tiny pieces.
1178	   */
1179	
1180	  UNUSED(fid);
1181	
1182	  /* Append data to frame buffer */
1183	
1184	  if (priv->frame_offset + data_len <= priv->frame_buflen)
1185	    {
1186	      memcpy(priv->frame_buf + priv->frame_offset,
1187	             payload + header_len, data_len);
1188	      priv->frame_offset += data_len;
1189	    }
1190	
1191	  /* (c) Deliver on EOF (primary) or max_frame_size (safety).
1192	   *
1193	   * EOF fires near the true frame boundary on most cameras.  Accept frames
1194	   * with ≥95% of expected size (Linux reference threshold) to handle the
1195	   * camera's occasional early/late EOF.  Max-size delivery catches the case
1196	   * where EOF is missed entirely.
1197	   *
1198	   * FID is NOT used — this camera toggles it ~20 times per frame.
1199	   */
1200	
1201	  /* EOF: deliver if ≥95% complete, ALWAYS reset. */
1202	
1203	  if (header->bmHeaderInfo & UVC_HEADER_EOF)
1204	    {
1205	      if (priv->max_frame_size > 0 &&
1206	          priv->frame_offset >= (priv->max_frame_size * 95 / 100) &&
1207	          priv->capture_cb != NULL && priv->user_buf != NULL)
1208	        {
1209	          size_t copy_len = priv->frame_offset;
1210	          if (copy_len > priv->user_buflen)
1211	            {
1212	              copy_len = priv->user_buflen;
1213	            }
1214	
1215	          memcpy(priv->user_buf, priv->frame_buf, copy_len);
1216	          priv->capture_cb(0, copy_len, 0, priv->capture_arg);
1217	        }
1218	
1219	      priv->frame_offset = 0;
1220	    }
1221	
1222	  /* Max-size safety: deliver if we've reached the expected frame size. */
1223	
1224	  if (priv->max_frame_size > 0 &&
1225	      priv->frame_offset >= priv->max_frame_size)
1226	    {
1227	      if (priv->capture_cb != NULL && priv->user_buf != NULL)
1228	        {
1229	          size_t copy_len = priv->max_frame_size;
1230	          if (copy_len > priv->user_buflen)
1231	            {
1232	              copy_len = priv->user_buflen;
1233	            }
1234	
1235	          memcpy(priv->user_buf, priv->frame_buf, copy_len);
1236	          priv->capture_cb(0, copy_len, 0, priv->capture_arg);
1237	        }
1238	
1239	      priv->frame_offset = 0;
1240	    }
1241	}
