1243	static int usbhost_uvc_stream_thread(int argc, FAR char *argv[])
1244	{
1245	  FAR struct usbhost_uvc_s *priv;
1246	  FAR struct usbhost_hubport_s *hport;
1247	  FAR struct usbhost_driver_s *drvr;
1248	  ssize_t nbytes;
1249	
1250	  priv = (FAR struct usbhost_uvc_s *)
1251	    ((uintptr_t)strtoul(argv[1], NULL, 16));
1252	
1253	  DEBUGASSERT(priv != NULL);
1254	  hport = priv->usbclass.hport;
1255	  DEBUGASSERT(hport != NULL && hport->drvr != NULL);
1256	  drvr = hport->drvr;
1257	
1258	  syslog(LOG_ERR, "UVC stream thread started, waiting for endpoint\n");
1259	
1260	  /* Wait for SET_INTERFACE to enable the streaming endpoint */
1261	
1262	  nxsem_wait_uninterruptible(&priv->stream_sem);
1263	
1264	  syslog(LOG_ERR, "UVC stream thread: endpoint ready, starting transfers\n");
1265	
1266	  while (!priv->disconnected && priv->streaming)
1267	    {
1268	      /* Receive isochronous data */
1269	
1270	      nbytes = DRVR_TRANSFER(drvr, priv->ep_stream,
1271	                             priv->xfer_buf, priv->xfer_buflen);
1272	
1273	      if (nbytes > 0)
1274	        {
1275	          usbhost_uvc_process_payload(priv, priv->xfer_buf, nbytes);
1276	        }
1277	      else if (nbytes < 0)
1278	        {
1279	          if (nbytes == -EAGAIN || nbytes == -ETIMEDOUT)
1280	            {
1281	              nxsig_usleep(1000);
1282	              continue;
1283	            }
1284	
1285	          syslog(LOG_ERR, "UVC stream: transfer error %zd\n", nbytes);
1286	
1287	          if (nbytes == -ENODEV || nbytes == -EPIPE)
1288	            {
1289	              break;
1290	            }
1291	
1292	          /* On transient errors (EIO/XACTERR), wait before retrying
1293	           * to avoid overwhelming the device.
1294	           */
1295	
1296	          nxsig_usleep(5000);  /* 5ms */
1297	        }
1298	    }
