1745	static int sunxi_ioc_wait(struct sunxi_epinfo_s *epinfo)
1746	{
1747	  int ret = OK;
1748	
1749	  /* Wait for the IOC event.  Loop to handle any false alarm semaphore
1750	   * counts.  For isochronous transfers, also poll the iTD status since
1751	   * the EHCI controller may not generate IOC interrupts for iTDs.
1752	   * Return an error if the task is canceled.
1753	   */
1754	
1755	  while (epinfo->iocwait)
1756	    {
1757	#ifndef CONFIG_USBHOST_ISOC_DISABLE
1758	      /* Isochronous IN: drain one payload from the iTD chain pipeline.
1759	       *
1760	       * Ring approach: slot j → itd[j % ISOC_ITD_POOL].  Each iTD is
1761	       * revisited every N*1ms by the controller.  We batch-harvest all
1762	       * completed iTDs (from ring_head forward) in one pass, re-arming
1763	       * each immediately so the controller never runs out of targets.
1764	       *
1765	       * Each DRVR_TRANSFER returns exactly one payload from the FIFO.
1766	       */
1767	
1768	      if (g_ring.epinfo == epinfo && g_ring.buf != NULL)
1769	        {
1770	          int spins = 0;
1771	          uint32_t per_uf = (uint32_t)g_ring.maxpacket *
1772	            (g_ring.epinfo->mult ? g_ring.epinfo->mult : 1);
1773	
1774	          for (; ; )
1775	            {
1776	              int scan;
1777	
1778	              /* (1) If we have buffered payloads, serve one immediately. */
1779	
1780	              if (g_ring.f_cnt > 0)
1781	                {
1782	                  uint32_t len = g_ring.fifo_len[g_ring.f_head];
1783	                  uint32_t seq = g_ring.fifo_seq[g_ring.f_head];
1784	                  uint8_t *src = g_ring.fifo +
1785	                                 (size_t)g_ring.f_head * ISOC_FIFO_SLOTSZ;
1786	                  size_t   n   = len > g_ring.user_buflen ?
1787	                                 g_ring.user_buflen : len;
1788	
1789	                  /* DIAG: check sequence continuity.  If seq jumps backward
1790	                   * or gaps, payloads are arriving out of order from the ring.
1791	                   */
1792	
1793	                  {
1794	                    static uint32_t last_seq = 0xffffffff;
1795	                    static uint32_t reorder_cnt;
1796	
1797	                    if (last_seq != 0xffffffff && seq != last_seq + 1)
1798	                      {
1799	                        if ((reorder_cnt++ % 50) == 0)
1800	                          {
1801	                            syslog(LOG_ERR,
1802	                              "REORDER: expected=%u got=%u delta=%d #%u\n",
1803	                              last_seq + 1, seq, (int)(seq - last_seq - 1),
1804	                              reorder_cnt);
1805	                          }
1806	                      }
1807	
1808	                    last_seq = seq;
1809	                  }
1810	
1811	                  memcpy(g_ring.user_buf, src, n);
1812	                  g_ring.f_head = (g_ring.f_head + 1) % ISOC_FIFO_SLOTS;
1813	                  g_ring.f_cnt--;
1814	
1815	                  epinfo->xfrd    = n;
1816	                  epinfo->result  = OK;
1817	                  epinfo->iocwait = false;
1818	                  return epinfo->result;
1819	                }
1820	
1821	              /* (2) FIFO empty — batch-harvest completed iTDs from the ring.
1822	               * Scan from ring_head forward; stop at the first iTD that is
1823	               * still ACTIVE (preserves chronological order).  Re-arm each
1824	               * harvested iTD immediately so the controller keeps filling it.
1825	               */
1826	
1827	              for (scan = 0; scan < ISOC_ITD_POOL; scan++)
1828	                {
1829	                  int idx = (g_ring.ring_head + scan) % ISOC_ITD_POOL;
1830	                  struct sunxi_itd_s *itd = &g_itdpool[idx];
1831	                  bool active = false;
1832	                  int uf;
1833	
1834	                  up_invalidate_dcache((uintptr_t)&itd->hw,
1835	                    (uintptr_t)&itd->hw + sizeof(struct ehci_itd_s));
1836	
1837	                  for (uf = 0; uf < ISOC_ITD_UFRAMES; uf++)
1838	                    {
1839	                      if (sunxi_swap32(itd->hw.trans[uf]) &
1840	                          ITD_TRAN_STATUS_ACTIVE)
1841	                        {
1842	                          active = true;
1843	                          break;
1844	                        }
1845	                    }
1846	
1847	                  if (active)
1848	                    {
1849	                      break;  /* Chronological boundary; stop harvest */
1850	                    }
1851	
1852	                  /* iTD completed: harvest its payloads into FIFO. */
1853	
1854	                  up_invalidate_dcache((uintptr_t)itd->buffer,
1855	                    (uintptr_t)itd->buffer +
1856	                    (size_t)ISOC_ITD_UFRAMES * per_uf);
1857	
1858	                  for (uf = 0; uf < ISOC_ITD_UFRAMES; uf++)
1859	                    {
1860	                      uint32_t tran = sunxi_swap32(itd->hw.trans[uf]);
1861	                      uint32_t rem  = (tran & ITD_TRAN_LENGTH_MASK) >>
1862	                                      ITD_TRAN_LENGTH_SHIFT;
1863	                      bool err = (tran & (ITD_TRAN_STATUS_XACTERR |
1864	                                          ITD_TRAN_STATUS_BABBLE |
1865	                                          ITD_TRAN_STATUS_DBERROR)) != 0;
1866	
1867	                      if (err || rem == 0)
1868	                        {
1869	                          continue;
1870	                        }
1871	
1872	                      /* DIAG: cumulative harvest counter, logged every 2000
1873	                       * payloads so we can compare with the UVC-layer counter
1874	                       * to find where payloads are lost.
1875	                       */
1876	
1877	                      {
1878	                        static uint32_t h_pls;
1879	                        static uint32_t h_bytes;
1880	
1881	                        h_pls++;
1882	                        h_bytes += rem;
1883	
1884	                        if ((h_pls % 2000) == 0)
1885	                          {
1886	                            syslog(LOG_ERR, "HARVEST: pls=%u bytes=%u\n",
1887	                                   h_pls, h_bytes);
1888	                          }
1889	                      }
1890	
1891	                      if (g_ring.f_cnt < ISOC_FIFO_SLOTS)
1892	                        {
1893	                          static uint32_t seq;  /* monotonic payload counter */
1894	                          uint32_t n = rem > ISOC_FIFO_SLOTSZ ?
1895	                                       ISOC_FIFO_SLOTSZ : rem;
1896	                          memcpy(g_ring.fifo +
1897	                                   (size_t)g_ring.f_tail *
1898	                                   ISOC_FIFO_SLOTSZ,
1899	                                 itd->buffer + (uint32_t)uf * per_uf, n);
1900	                          g_ring.fifo_len[g_ring.f_tail] =
1901	                            (uint16_t)n;
1902	                          g_ring.fifo_seq[g_ring.f_tail] = seq++;
1903	                          g_ring.f_tail =
1904	                            (g_ring.f_tail + 1) % ISOC_FIFO_SLOTS;
1905	                          g_ring.f_cnt++;
1906	                        }
1907	                      else
1908	                        {
1909	                          static uint32_t diag_full;
1910	                          if ((diag_full++ % 200) == 0)
1911	                            {
1912	                              syslog(LOG_ERR, "HARVEST fifo full #%u\n",
1913	                                     diag_full);
1914	                            }
1915	                        }
1916	                    }
1917	
1918	                  /* Re-arm immediately so the controller keeps filling. */
1919	
1920	                  {
1921	                    FAR uint8_t *buffer = g_ring.buf +
1922	                                          (size_t)idx * ISOC_ITD_BUFSZ;
1923	                    sunxi_itd_arm(idx, buffer, g_ring.nlp);
1924	                  }
1925	
1926	                  g_ring.ring_head =
1927	                    (g_ring.ring_head + 1) % ISOC_ITD_POOL;
1928	                }
1929	
1930	              /* (3) All iTDs polled but some still ACTIVE, or FIFO empty.
1931	               * Bail out if canceled, else wait.
1932	               */
1933	
1934	              if (!epinfo->iocwait)
1935	                {
1936	                  return epinfo->result;
1937	                }
1938	
1939	              /* The harvest scan above found no completed iTDs.  Instead of
1940	               * blocking for a full 1ms tick (which limits throughput to
1941	               * ~2300 payload/sec), do a brief micro-frame delay then
1942	               * immediately loop back to harvest again.  The IOC interrupt
1943	               * also posts the semaphore, so if the delay isn't enough the
1944	               * semaphore wakes us.

1940	               * blocking for a full 1ms tick (which limits throughput to
1941	               * ~2300 payload/sec), do a brief micro-frame delay then
1942	               * immediately loop back to harvest again.  The IOC interrupt
1943	               * also posts the semaphore, so if the delay isn't enough the
1944	               * semaphore wakes us.
1945	               *
1946	               * 125µs = one micro-frame.  8 such delays = 1ms = one iTD
1947	               * completion.  With N=32 iTDs, the controller fills one iTD
1948	               * per 1ms, so we only need to wait ~1ms before the next one
1949	               * is ready.
1950	               */
1951	
1952	              up_udelay(125);
1953	
1954	              if (++spins > 8000)        /* ~1s watchdog */
1955	                {
1956	                  epinfo->xfrd    = 0;
1957	                  epinfo->result  = -EAGAIN;
1958	                  epinfo->iocwait = false;
1959	                  return epinfo->result;
1960	                }
1961	            }
1962	        }
1963	      else
1964	#endif
1965	        {
1966	          ret = nxsem_wait_uninterruptible(&epinfo->iocsem);
1967	        }
1968	
1969	      if (ret < 0)
1970	        {
1971	          break;
1972	        }
1973	    }
1974	
1975	  return ret < 0 ? ret : epinfo->result;
1976	}
