1988	static void sunxi_qh_enqueue(struct sunxi_qh_s *qhead, struct sunxi_qh_s *qh)
1989	{
1990	  uintptr_t physaddr;
1991	
1992	  /* Set the internal fqp field.  When we transverse the QH list later,
1993	   * we need to know the correct place to start because the overlay may no
1994	   * longer point to the first qTD entry.
1995	   */
1996	
1997	  qh->fqp = qh->hw.overlay.nqp;
1998	  sunxi_qh_dump(qh, NULL, NULL);
1999	
2000	  /* Add the new QH to the head of the asynchronous queue list.
2001	   *
2002	   * First, attach the old head as the new QH HLP and flush the new QH and
2003	   * its attached qTDs to RAM.
2004	   */
2005	
2006	  qh->hw.hlp = qhead->hw.hlp;
2007	  sunxi_qh_flush(qh);
2008	
2009	  /* Then set the new QH as the first QH in the asynchronous queue and flush
2010	   * the modified head to RAM.
2011	   */
2012	
2013	  physaddr = (uintptr_t)sunxi_physramaddr((uintptr_t)qh);
2014	  qhead->hw.hlp = sunxi_swap32(physaddr | QH_HLP_TYP_QH);
2015	
2016	  up_flush_dcache((uintptr_t)&qhead->hw,
2017	                  (uintptr_t)&qhead->hw + sizeof(struct ehci_qh_s));
2018	}
