2815	 * Name: sunxi_itd_arm
2816	 *
2817	 * Description:
2818	 *   (Re)program one ring iTD to receive up to ISOC_ITD_UFRAMES payloads,
2819	 *   one per micro-frame.  Each transaction i reads into the iTD's own DMA
2820	 *   buffer at offset i*maxpacket, so the payloads land in separate slots and
2821	 *   can be handed to the UVC layer one at a time (each still begins with its
2822	 *   own 12-byte payload header at offset 0).  nlp is preserved so the
2823	 *   periodic (interrupt) schedule that follows the iTD keeps running.
2824	 *
2825	 ****************************************************************************/
2826	
2827	static void sunxi_itd_arm(int idx, FAR uint8_t *buffer, uint32_t nlp)
2828	{
2829	  struct sunxi_itd_s    *itd    = &g_itdpool[idx];
2830	  struct sunxi_epinfo_s *epinfo = g_ring.epinfo;
2831	  uintptr_t  bufphys;
2832	  uint32_t   maxpkt = g_ring.maxpacket;
2833	
2834	  /* Bytes per micro-frame: for high-bandwidth endpoints the controller may
2835	   * issue up to `mult` packets per micro-frame back-to-back, so one payload
2836	   * slot spans mult*maxpacket bytes.  For mult==1 this is just maxpacket.
2837	   */
2838	
2839	  uint32_t   per_uf = maxpkt * (epinfo->mult ? epinfo->mult : 1);
2840	  int        uf;
2841	
2842	  itd->epinfo = epinfo;
2843	  itd->buffer = buffer;
2844	  itd->buflen = ISOC_ITD_BUFSZ;
2845	  itd->result = -EBUSY;
2846	
2847	  bufphys = (uintptr_t)sunxi_physramaddr((uintptr_t)buffer);
2848	
2849	  /* Buffer Page Pointer List (bpl[0..6]) spans 7 physical 4K pages starting
2850	   * at the (page-aligned) base of this iTD's buffer.  ISOC_ITD_BUFSZ (8K)
2851	   * needs at most 3 pages, but program all 7 defensively.  The per-page base
2852	   * must be page-aligned; the per-transaction XOFFS supplies the low 12 bits.
2853	   */
2854	
2855	  {
2856	    uintptr_t pgbase = bufphys & ITD_BUFPTR_MASK;
2857	
2858	    itd->hw.bpl[0] = sunxi_swap32(
2859	      ((uint32_t)epinfo->devaddr << ITD_BUFPTR0_DEVADDR_SHIFT) |
2860	      ((uint32_t)epinfo->epno << ITD_BUFPTR0_ENDPT_SHIFT) |
2861	      (pgbase & ITD_BUFPTR_MASK));
2862	
2863	    itd->hw.bpl[1] = sunxi_swap32(
2864	      ((uint32_t)maxpkt << ITD_BUFPTR1_MAXPKT_SHIFT) |
2865	      (epinfo->dirin ? ITD_BUFPTR1_DIRIN : ITD_BUFPTR1_DIROUT) |
2866	      ((pgbase + 0x1000) & ITD_BUFPTR_MASK));
2867	
2868	    {
2869	      uint32_t multi_val = (epinfo->mult == 3) ? ITD_BUFPTR2_MULTI_3 :
2870	                           (epinfo->mult == 2) ? ITD_BUFPTR2_MULTI_2 :
2871	                                                 ITD_BUFPTR2_MULTI_1;
2872	      itd->hw.bpl[2] = sunxi_swap32(multi_val |
2873	                                    ((pgbase + 0x2000) & ITD_BUFPTR_MASK));
2874	    }
2875	
2876	    itd->hw.bpl[3] = sunxi_swap32((pgbase + 0x3000) & ITD_BUFPTR_MASK);
2877	    itd->hw.bpl[4] = sunxi_swap32((pgbase + 0x4000) & ITD_BUFPTR_MASK);
2878	    itd->hw.bpl[5] = sunxi_swap32((pgbase + 0x5000) & ITD_BUFPTR_MASK);
